#!/bin/sh
# Builds the Android app (android/compose, Kotlin + Compose, docs/compose-plan.md):
# dist/kzsigner-<version>-android.apk, for phones (arm64) and the emulator (x86_64), with the
# core as libkzsigner_ffi.so and its Kotlin bindings generated by uniffi-bindgen. cargo builds
# the Rust library (through scripts/cargo.sh); Gradle (android/, pinned versions) adds the
# Kotlin side, AndroidX and signs.
#
#   ANDROID_HOME=... ANDROID_NDK_ROOT=... sh scripts/apk.sh
#
# Needs: the NDK (r30), build-tools 37.0.0, platforms;android-37.0 and a JDK 17 or newer (25
# on CI). Gradle itself is downloaded once (pinned version, checked against its SHA-256) into
# ~/.cache/kzsigner-gradle, or taken from KZSIGNER_GRADLE. Two builds of a commit give the same
# APK.
#
# KZSIGNER_UITEST=1 also builds the emulator tests (UI Automator, android/uitest) as
# target/apk-uitest/kzsigner-uitest.apk. CI runs them with scripts/android-selftest.sh.
#
# Signing: with KZSIGNER_KEYSTORE (+ KZSIGNER_KEYSTORE_PASS, KZSIGNER_KEY_ALIAS) when set,
# else with android/dev.keystore, a development key whose password is in
# android/compose/build.gradle.kts. A phone keeps an app only while updates come with the same
# key: a dev build has to be uninstalled before a release build can be installed.
set -eu
cd "$(dirname "$0")/.."
: "${ANDROID_HOME:?set ANDROID_HOME to the Android SDK}"
: "${ANDROID_NDK_ROOT:?set ANDROID_NDK_ROOT to the NDK}"
export ANDROID_HOME
TC=$ANDROID_NDK_ROOT/toolchains/llvm/prebuilt/linux-x86_64/bin
V=$(sed -n 's/^version = "\(.*\)"/\1/p' Cargo.toml | head -1)
GRADLE_VERSION=9.9.2
GRADLE_SHA256=971fcd7150ca4ba04852c0b2ca0d2d0ab9468e14b03473eab19528809914c76b

TARGETS="aarch64-linux-android x86_64-linux-android"
TASKS=":compose:assembleRelease"
[ -n "${KZSIGNER_UITEST:-}" ] && TASKS="$TASKS :uitest:assembleDebug"
FFI=target/android-ffi
OUT=dist/kzsigner-$V-android.apk
# a release must not be signed with the development key, whose password is public
case "$V" in
*-*) ;;
*) [ -n "${KZSIGNER_KEYSTORE:-}" ] || {
    echo "release $V: set KZSIGNER_KEYSTORE (the release signing key); the dev key is for -dev versions only" >&2
    exit 1
} ;;
esac

# the Rust library, for each phone architecture
rm -rf "$FFI"
for t in $TARGETS; do
    T=$(echo "$t" | tr 'a-z-' 'A-Z_')
    export "CARGO_TARGET_${T}_LINKER=$TC/${t}30-clang"
    tt=$(echo "$t" | tr '-' '_')
    export "CC_${tt}=$TC/${t}30-clang" "AR_${tt}=$TC/llvm-ar"
    sh scripts/cargo.sh build --release --locked --target "$t" -p kzsigner-ffi
    case $t in
    aarch64-*) abi=arm64-v8a ;;
    x86_64-*) abi=x86_64 ;;
    esac
    mkdir -p "$FFI/$abi"
    cp "target/$t/release/libkzsigner_ffi.so" "$FFI/$abi/"
done
# the core's Kotlin bindings, read from a host build of the same library (the release .so
# files are stripped of what uniffi-bindgen reads)
cargo build --locked -p kzsigner-ffi
rm -rf target/uniffi-kotlin
cargo run -q --locked -p kzsigner-ffi --features bindgen --bin uniffi-bindgen -- generate \
    --library "target/debug/libkzsigner_ffi.$(case "$(uname)" in Darwin) echo dylib ;; *) echo so ;; esac)" \
    --language kotlin --no-format --out-dir target/uniffi-kotlin

# Gradle, pinned and checked
if [ -n "${KZSIGNER_GRADLE:-}" ]; then
    GRADLE=$KZSIGNER_GRADLE
else
    G=${XDG_CACHE_HOME:-$HOME/.cache}/kzsigner-gradle
    GRADLE=$G/gradle-$GRADLE_VERSION/bin/gradle
    if [ ! -x "$GRADLE" ]; then
        mkdir -p "$G"
        zip=$G/gradle-$GRADLE_VERSION-bin.zip
        [ -f "$zip" ] || curl -sSfL -o "$zip" "https://services.gradle.org/distributions/gradle-$GRADLE_VERSION-bin.zip"
        echo "$GRADLE_SHA256  $zip" | sha256sum -c - > /dev/null || {
            echo "gradle-$GRADLE_VERSION-bin.zip: wrong SHA-256" >&2
            rm -f "$zip"
            exit 1
        }
        (cd "$G" && unzip -q -o "gradle-$GRADLE_VERSION-bin.zip")
    fi
fi

# shellcheck disable=SC2086
"$GRADLE" -q -p android --no-daemon --console=plain $TASKS \
    -Pkzsigner.version="$V" \
    -Pkzsigner.ffiLibs="$(pwd)/$FFI" -Pkzsigner.ffiKotlin="$(pwd)/target/uniffi-kotlin"
mkdir -p "$(dirname "$OUT")"
cp target/gradle-compose/outputs/apk/release/compose-release.apk "$OUT"
if [ -n "${KZSIGNER_UITEST:-}" ]; then
    mkdir -p target/apk-uitest
    cp target/gradle-uitest/outputs/apk/debug/uitest-debug.apk target/apk-uitest/kzsigner-uitest.apk
fi
"$ANDROID_HOME/build-tools/37.0.0/apksigner" verify --print-certs "$OUT" | head -3
ls -la "$OUT"
